import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { createKeyword } from '../services/api';

const CreateKeyword = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    imagePosition: 'center',
    image: null
  });
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setFormData({
        ...formData,
        image: file
      });

      // Create a preview URL for the selected image
      const reader = new FileReader();
      reader.onloadend = () => {
        setPreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Basic validation
    if (!formData.title || !formData.description || !formData.image) {
      setError('Please fill in all fields and select an image.');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const data = new FormData();
      data.append('title', formData.title);
      data.append('description', formData.description);
      data.append('imagePosition', formData.imagePosition);
      data.append('image', formData.image);

      await createKeyword(data);
      navigate('/keywords');
    } catch (err) {
      setError(err.response?.data?.message || 'Failed to create keyword. Please try again.');
      setLoading(false);
    }
  };

  // Image position options
  const positionOptions = [
    { value: 'center', label: 'Center' },
    { value: 'top', label: 'Top' },
    { value: 'bottom', label: 'Bottom' },
    { value: 'left', label: 'Left' },
    { value: 'right', label: 'Right' },
    { value: 'top left', label: 'Top Left' },
    { value: 'top right', label: 'Top Right' },
    { value: 'bottom left', label: 'Bottom Left' },
    { value: 'bottom right', label: 'Bottom Right' }
  ];

  return (
    <div className="create-keyword-page">
      <div className="header">
        <h1>Create New Keyword</h1>
      </div>

      <form className="create-keyword-form" onSubmit={handleSubmit}>
        <h2 className="form-title">Keyword Details</h2>

        {error && <div className="error-message">{error}</div>}

        <div className="form-group">
          <label htmlFor="title">Title *</label>
          <input
            type="text"
            id="title"
            name="title"
            className="form-control"
            value={formData.title}
            onChange={handleChange}
            placeholder="Enter keyword title"
            required
          />
        </div>

        <div className="form-group">
          <label htmlFor="description">Description *</label>
          <textarea
            id="description"
            name="description"
            className="form-control"
            value={formData.description}
            onChange={handleChange}
            placeholder="Enter keyword description"
            rows="4"
            required
          ></textarea>
        </div>

        <div className="form-group">
          <label htmlFor="image">Background Image *</label>
          <input
            type="file"
            id="image"
            name="image"
            className="form-control"
            onChange={handleImageChange}
            accept="image/*"
            required
          />
          <small className="form-text">
            Upload a background image for your keyword. Max size: 5MB. Supported formats: JPEG, PNG, GIF.
          </small>
        </div>

        <div className="form-group">
          <label htmlFor="imagePosition">Image Position</label>
          <select
            id="imagePosition"
            name="imagePosition"
            className="form-control"
            value={formData.imagePosition}
            onChange={handleChange}
          >
            {positionOptions.map(option => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
          <small className="form-text">
            Choose how the background image should be positioned within the keyword card.
          </small>
        </div>

        <div className="image-preview">
          {preview ? (
            <div 
              className="keyword-preview-image" 
              style={{
                backgroundImage: `url(${preview})`,
                backgroundSize: 'cover',
                backgroundPosition: formData.imagePosition,
                height: '100%',
                width: '100%',
                borderRadius: '4px'
              }}
            ></div>
          ) : (
            <div className="image-preview-text">Image preview will appear here</div>
          )}
        </div>

        <div className="form-actions">
          <button 
            type="button" 
            className="btn btn-secondary"
            onClick={() => navigate('/keywords')}
          >
            Cancel
          </button>
          <button 
            type="submit" 
            className="btn btn-primary"
            disabled={loading}
          >
            {loading ? 'Creating...' : 'Create Keyword'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default CreateKeyword;
